if __name__ == "__main__":
    lines, out = [], []
    for i, (pid, (nm, addr, c, r, st, match)) in enumerate(Q.items()):
        lines.append("https://yandex.ru/maps/1/moscow-and-moscow-oblast/?pl%d=1112p&text=%s" % (i, urllib.parse.quote(nm + ", " + addr)))
        q = {"id": "pl12-" + pid, "lat": c[0], "lon": c[1], "radius": r, "name": match}
        if st:
            q["street"] = st
        out.append(q)
    p = os.path.join(ROOT, "auto/fetch-queue.txt")
    old = open(p).read().rstrip("\n").split("\n")
    open(p, "w").write("\n".join(old + [l for l in lines if l not in old]) + "\n")
    p = os.path.join(ROOT, "auto/osm-queries.json")
    old = [x for x in json.load(open(p)) if not x["id"].startswith("pl12-")]
    json.dump(old + out, open(p, "w"), ensure_ascii=False, indent=1)
    print(len(out))
